Here's an example of how you can design an EXP UI slider and system using Fungus in Unity. This example includes a slider that increments the EXP needed for each level, and updates the slider in real-time.

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using Fungus;

public class EXPUI : MonoBehaviour
{
    // Slider components
    public Slider expSlider;
    public Slider maxExpSlider;

    // Current EXP level and max EXP level
    public int currentExpLevel = 1;
    public int maxExpLevel = 99;

    // Increment EXP per level
    public int expIncrement = 15;

    // Update EXP slider
    private void Start()
    {
        // Initialize the slider
        expSlider.value = 0;
        maxExpSlider.value = 0;

        // Update the slider to show the current EXP
        UpdateEXP();
    }

    // Update the EXP slider
    private void UpdateEXP()
    {
        // Calculate the EXP to display on the slider
        float expToDisplay = (float)currentExpLevel / (float)maxExpLevel * 100;

        // Update the slider value
        expSlider.value = expToDisplay;

        // Update the slider UI
        expSlider.transform.localScale = new Vector3(1, expToDisplay / 100f, 1);
    }

    // Level up the player
    public void LevelUp()
    {
        // Increment the current EXP level
        currentExpLevel++;

        // Update the EXP slider
        UpdateEXP();

        // Check if we've reached the max EXP level
        if (currentExpLevel > maxExpLevel)
        {
            currentExpLevel = maxExpLevel;
        }

        // Increase the EXP increment for the next level
        expIncrement += 10;
    }

    // Increase the EXP increment for the next level
    public void IncreaseEXPIncrement()
    {
        // Update the EXP increment
        expIncrement += 10;

        // Check if we've reached the max EXP level
        if (expIncrement > 100)
        {
            expIncrement = 100;
        }
    }

    // Increase the EXP increment for the next level
    public void IncreaseEXPIncrement(int amount)
    {
        // Update the EXP increment
        expIncrement += amount;

        // Check if we've reached the max EXP level
        if (expIncrement > 100)
        {
            expIncrement = 100;
        }
    }
}
```

To use this script in your Unity project, you'll need to follow these steps:

1. Create a new UI Canvas in your scene by going to `GameObject` > `UI` > `Canvas`.
2. Create a new Slider component by going to `GameObject` > `UI` > `Slider`.
3. Create a new Slider component for the max EXP level by going to `GameObject` > `UI` > `Slider`.
4. Attach the `EXPUI` script to a GameObject in your scene.
5. In the Inspector, assign the Slider components to the `expSlider` and `maxExpSlider` variables.
6. In the Inspector, assign the EXP increment values to the `expIncrement` variable.
7. Assign the `LevelUp` method to a button in the scene.
8. Assign the `IncreaseEXPIncrement` method to another button in the scene.
9. Assign the `IncreaseEXPIncrement` method with a specific amount to another button in the scene.

This script will display a slider that increments the EXP needed for each level, and updates the slider in real-time. You can use the `LevelUp` method to level up your player, and the `IncreaseEXPIncrement` method to increase the EXP increment for the next level.

Here's an example of a Python function that converts a function to a JSON format using the `inspect` module, `json` module, and `type` module.

**Function Conversion Code:**

```python
import inspect
import json
from typing import Callable

def convert_to_json(func: Callable, indent: int = 0) -> str:
    """
    Convert a Python function to a JSON format.

    Args:
        func (Callable): The Python function to convert.
        indent (int, optional): The number of spaces to indent the JSON output. Defaults to 0.

    Returns:
        str: The JSON representation of the function.
    """
    # Get the function's signature
    signature = inspect.signature(func)

    # Create a dictionary to store the function's parameters
    params = {}
    for param in signature.parameters.values():
        params[param.name] = param.annotation
    params['return_type'] = signature.return_annotation

    # Create a dictionary to store the function's locals
    locals = {}
    for key, value in inspect.getmembers(func):
        if inspect.isfunction(value) and key != '__name__' and key != '__doc__':
            locals[key] = value
    locals['locals'] = locals

    # Convert the function's parameters and locals to JSON
    json_str = json.dumps({
        'name': func.__name__,
        'signature': inspect.signature(func).parameters,
        'params': params,
        'locals': locals
    }, indent=indent)

    return json_str

# Example usage:

def add(a: int, b: int) -> int:
    return a + b

print(convert_to_json(add))
```

This code defines a `convert_to_json` function that takes a Python function `func` and an optional `indent` parameter. It uses the `inspect` module to get the function's signature, and the `json` module to convert the function's parameters and locals to JSON.

The function returns a JSON string representation of the function, with the following structure:

```json
{
    "name": "add",
    "signature": {
        "parameters": {
            "a": "int",
            "b": "int"
        },
        "return_type": "int"
    },
    "params": {
        "a": "int",
        "b": "int"
    },
    "locals": {
        "a": "int",
        "b": "int"
    }
}
```

**Output:**

```
{
    "name": "add",
    "signature": {
        "parameters": {
            "a": "int",
            "b": "int"
        },
        "return_type": "int"
    },
    "params": {
        "a": "int",
        "b": "int"
    },
    "locals": {
        "a": "int",
        "b": "int"
    }
}
```

This JSON representation is a valid JSON object, which can be used to serialize and deserialize Python functions using a library like `pydantic`.

Here's a simple Java program that can understand and display fractions and perform basic arithmetic operations like addition, subtraction, multiplication, and division.

**FractionCalculator.java**
```java
import java.util.Scanner;

public class FractionCalculator {

    // Enum for fraction types
    enum FractionType {
        DENOMINATOR_1,
        DENOMINATOR_2
    }

    // Class to represent a fraction
    static class Fraction {
        private double numerator;
        private double denominator;

        public Fraction(double numerator, double denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }

        public double getNumerator() {
            return numerator;
        }

        public double getDenominator() {
            return denominator;
        }

        @Override
        public String toString() {
            return numerator + "/" + denominator;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Fraction Calculator");
        System.out.println("-----------------");

        while (true) {
            System.out.println("1. Display Fraction");
            System.out.println("2. Add Fractions");
            System.out.println("3. Subtract Fractions");
            System.out.println("4. Multiply Fractions");
            System.out.println("5. Divide Fractions");
            System.out.println("6. Exit");

            System.out.print("Choose an option: ");
            int option = scanner.nextInt();

            switch (option) {
                case 1:
                    displayFraction(scanner);
                    break;
                case 2:
                    addFractions(scanner);
                    break;
                case 3:
                    subtractFractions(scanner);
                    break;
                case 4:
                    multiplyFractions(scanner);
                    break;
                case 5:
                    divideFractions(scanner);
                    break;
                case 6:
                    System.out.println("Exiting...");
                    return;
                default:
                    System.out.println("Invalid option. Please choose a valid option.");
            }
        }
    }

    private static void displayFraction(Scanner scanner) {
        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator = scanner.next();

        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator = scanner.next();

        try {
            Fraction fraction = new Fraction(Integer.parseInt(numerator), Integer.parseInt(denominator));
            System.out.println(fraction);
        } catch (NumberFormatException e) {
            System.out.println("Invalid input. Please enter numbers only.");
        }
    }

    private static void addFractions(Scanner scanner) {
        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator1 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator1 = scanner.next();

        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator2 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator2 = scanner.next();

        Fraction fraction1 = new Fraction(Integer.parseInt(numerator1), Integer.parseInt(denominator1));
        Fraction fraction2 = new Fraction(Integer.parseInt(numerator2), Integer.parseInt(denominator2));

        System.out.println("Result: " + (fraction1 + fraction2));
    }

    private static void subtractFractions(Scanner scanner) {
        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator1 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator1 = scanner.next();

        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator2 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator2 = scanner.next();

        Fraction fraction1 = new Fraction(Integer.parseInt(numerator1), Integer.parseInt(denominator1));
        Fraction fraction2 = new Fraction(Integer.parseInt(numerator2), Integer.parseInt(denominator2));

        System.out.println("Result: " + (fraction1 - fraction2));
    }

    private static void multiplyFractions(Scanner scanner) {
        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator1 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator1 = scanner.next();

        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator2 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator2 = scanner.next();

        Fraction fraction1 = new Fraction(Integer.parseInt(numerator1), Integer.parseInt(denominator1));
        Fraction fraction2 = new Fraction(Integer.parseInt(numerator2), Integer.parseInt(denominator2));

        System.out.println("Result: " + (fraction1 * fraction2));
    }

    private static void divideFractions(Scanner scanner) {
        System.out.print("Enter the first fraction (e.g., 1/2): ");
        String numerator1 = scanner.next();
        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String denominator1 = scanner.next();

        System.out.print("Enter the second fraction (e.g., 3/4): ");
        String numerator2 = scanner.next();

        Fraction fraction1 = new Fraction(Integer.parseInt(numerator1), Integer.parseInt(denominator1));
        Fraction fraction2 = new Fraction(Integer.parseInt(numerator2), Integer.parseInt(denominator2));

        System.out.println("Result: " + (fraction1 / fraction2));
    }
}
```

**How to run:**

1. Save the code in a file named `FractionCalculator.java`.
2. Compile the code using `javac FractionCalculator.java`.
3. Run the program using `java FractionCalculator`.
4. Follow the prompts to perform calculations and view results.

Note: This program assumes that the user will enter valid input, such as numbers only. It also assumes that the fractions are displayed in the format `numerator/denominator`.

