requirements.txt
```

**app.py:**

```python
from flask import Flask, render_template

app = Flask(__name__)

# Sample data for the home page
data = {
    "button1": "Click me!",
    "button2": "Scroll down",
}

@app.route("/")
def index():
    """Home page route."""
    return render_template("index.html", data=data)

@app.route("/button1")
def button1():
    """Redirect to button1 page."""
    return render_template("base.html", data=data)

@app.route("/button1/<string:script_name>")
def button1_script(script_name):
    """Redirect to button1 script page."""
    return render_template("script.html", script_name=script_name)

if __name__ == "__main__":
    app.run(debug=True)
```

