**models/user.dart**
```dart
class User {
  final String _id;
  final String _username;
  final String _password;

  User({required this._id, required this._username, required this._password});

  factory User.fromJson(Map<String, dynamic> json) {
    return User(
      _id: json['id'],
      _username: json['username'],
      _password: json['password'],
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': _id,
      'username': _username,
      'password': _password,
    };
  }
}
```

**services/auth_service.dart**
```dart
class AuthService {
  Future<bool> login(String username, String password) async {
    // Simulate a database query
    final users = [
      User(_id: 1, _username: 'john', _password: 'password'),
    ];
    for (var user in users) {
      if (user._password == password && user._username == username) {
        return true;
      }
    }
    return false;
  }
}
```

